<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/catalog.php';
require_auth();
$user = current_user(); $categories = product_categories(); $sizes = product_sizes(); $conditions = product_conditions(); $origins = product_origins(); $statuses = ['Disponível', 'Vendido', 'Reservado']; $action = $_GET['action'] ?? 'list'; $id = (int) ($_GET['id'] ?? 0); $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $id = (int) ($_POST['id'] ?? 0); $categoryCode = $_POST['category'] ?? ''; $categoryData = $categories[$categoryCode] ?? null; $subcategoryCode = $_POST['subcategory'] ?? '';
    $data = ['name'=>trim($_POST['name']??''), 'size'=>$_POST['size']??'', 'condition_grade'=>$_POST['condition_grade']??'', 'price'=>trim($_POST['price']??''), 'entry_date'=>trim($_POST['entry_date']??''), 'origin'=>$_POST['origin']??'', 'contact_id'=>(int)($_POST['contact_id']??0)?:null, 'status'=>$_POST['status']??'', 'notes'=>trim($_POST['notes']??'')];
    if (strlen($data['name']) < 2 || !$categoryData || !array_key_exists($subcategoryCode, $categoryData['subcategories']) || !in_array($data['size'], $sizes, true) || !in_array($data['condition_grade'], $conditions, true) || !is_numeric($data['price']) || $data['price'] < 0 || !$data['entry_date'] || !in_array($data['origin'], $origins, true) || !in_array($data['status'], $statuses, true)) $error = 'Escolha opções válidas e preencha os campos obrigatórios.';
    else { $subcategory = $categoryData['subcategories'][$subcategoryCode]; $codeQuery = $id ? db()->prepare('SELECT code FROM products WHERE id=? AND user_id=?') : null; if ($codeQuery) { $codeQuery->execute([$id,$user['id']]); $productCode=$codeQuery->fetchColumn(); } else $productCode=next_product_code(db(),$user['id'],$categoryData['name'],$subcategoryCode); $values=[$data['name'],$categoryData['name'],$subcategory,$data['size'],$data['condition_grade'],$data['price'],$data['entry_date'],$data['origin'],$data['contact_id'],$data['status'],$data['notes']]; if($id){$sql='UPDATE products SET name=?,category=?,subcategory=?,size=?,condition_grade=?,price=?,entry_date=?,origin=?,contact_id=?,status=?,notes=? WHERE id=? AND user_id=?';$values=[...$values,$id,$user['id']];}else{$sql='INSERT INTO products (code,name,category,subcategory,size,condition_grade,price,entry_date,origin,contact_id,status,notes,user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)';$values=[$productCode,...$values,$user['id']];} db()->prepare($sql)->execute($values); flash('success',$id?'Peça atualizada.':'Peça adicionada ao estoque.'); redirect('clients.php'); }
}
if ($action==='delete' && $id) { db()->prepare('DELETE FROM products WHERE id=? AND user_id=?')->execute([$id,$user['id']]); flash('success','Peça removida.'); redirect('clients.php'); }
$editing=null; if($action==='edit'&&$id){$query=db()->prepare('SELECT * FROM products WHERE id=? AND user_id=?');$query->execute([$id,$user['id']]);$editing=$query->fetch();if(!$editing)redirect('clients.php');}
$query=db()->prepare('SELECT id,name,is_supplier,is_buyer FROM contacts WHERE user_id=? ORDER BY name');$query->execute([$user['id']]);$contacts=$query->fetchAll(); $status=$_GET['status']??''; $categoryFilter=$_GET['category']??''; $subcategoryFilter=$_GET['subcategory']??''; $search=trim($_GET['search']??''); $subcategoryOptions=product_subcategories();
$sql='SELECT * FROM products WHERE user_id=?';$values=[$user['id']];if(in_array($status,$statuses,true)){$sql.=' AND status=?';$values[]=$status;}if($categoryFilter){$sql.=' AND category=?';$values[]=$categoryFilter;}if(isset($subcategoryOptions[$subcategoryFilter])){$sql.=' AND subcategory=?';$values[]=$subcategoryOptions[$subcategoryFilter];}if($search){$sql.=' AND (name LIKE ? OR code LIKE ?)';$values[]='%'.$search.'%';$values[]='%'.$search.'%';}$sql.=' ORDER BY entry_date DESC,id DESC';$query=db()->prepare($sql);$query->execute($values);$products=$query->fetchAll();
require __DIR__.'/partials/header.php';
if($editing||$action==='create'){$form=$editing?:array_fill_keys(['name','category','subcategory','size','condition_grade','price','entry_date','origin','contact_id','status','notes'],'');$selectedCode='';foreach($categories as $code=>$item)if($item['name']===($form['category']??''))$selectedCode=$code;$selectedSubcategoryCode='';foreach($categories as $item)foreach($item['subcategories'] as $code=>$name)if($name===($form['subcategory']??''))$selectedSubcategoryCode=$code;}
?>
<?php if($editing||$action==='create'): ?><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="page-title h3"><?= $editing?'Editar peça':'Adicionar peça' ?></h1><a href="clients.php" class="btn btn-outline-secondary"><i data-lucide="arrow-left"></i> Voltar</a></div><div class="panel"><form method="post" data-validate novalidate><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= $editing['id']??'' ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome *</label><input class="form-control" name="name" required value="<?= e($form['name']) ?>"></div><div class="col-md-3"><label class="form-label">Categoria *</label><select class="form-select" name="category" required><?php foreach($categories as $code=>$item): ?><option value="<?= $code ?>" <?= $selectedCode===$code?'selected':'' ?>><?= e($item['name']) ?> (<?= $code ?>)</option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Subcategoria *</label><select class="form-select" name="subcategory" required><?php foreach($subcategoryOptions as $code=>$name): ?><option value="<?= $code ?>" <?= $selectedSubcategoryCode===$code?'selected':'' ?>><?= e($name) ?> (<?= $code ?>)</option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Tamanho *</label><select class="form-select" name="size" required><?php foreach($sizes as $option): ?><option <?= $form['size']===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Condição *</label><select class="form-select" name="condition_grade" required><?php foreach($conditions as $option): ?><option <?= $form['condition_grade']===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Preço *</label><input class="form-control" type="number" step="0.01" min="0" name="price" required value="<?= e((string)$form['price']) ?>"></div><div class="col-md-3"><label class="form-label">Entrada *</label><input class="form-control" type="date" name="entry_date" required value="<?= e($form['entry_date']?:date('Y-m-d')) ?>"></div><div class="col-md-4"><label class="form-label">Origem *</label><select class="form-select" name="origin" required><?php foreach($origins as $option): ?><option <?= $form['origin']===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Contato</label><select class="form-select" name="contact_id"><option value="">Sem vínculo</option><?php foreach($contacts as $contact): ?><option value="<?= $contact['id'] ?>" <?= (string)($form['contact_id']??'')===(string)$contact['id']?'selected':'' ?>><?= e($contact['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Status *</label><select class="form-select" name="status" required><?php foreach($statuses as $option): ?><option <?= $form['status']===$option?'selected':'' ?>><?= $option ?></option><?php endforeach; ?></select></div></div><button class="btn btn-primary mt-4"><i data-lucide="save"></i> Salvar peça</button></form></div>
<?php else: ?><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">Acervo</div><h1 class="page-title h3 mb-0">Estoque de peças</h1></div><a class="btn btn-coral" href="clients.php?action=create"><i data-lucide="plus"></i> Adicionar peça</a></div><div class="category-legend"><?php foreach($categories as $code=>$item): ?><a class="category-chip <?= $categoryFilter===$item['name']?'active':'' ?>" href="clients.php?category=<?= urlencode($item['name']) ?>"><i data-lucide="<?= e($item['icon']) ?>"></i><?= e($item['name']) ?></a><?php endforeach; ?></div><form class="panel mb-3" method="get"><div class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label small">Buscar peça ou código</label><input class="form-control" name="search" value="<?= e($search) ?>"></div><div class="col-md-3"><label class="form-label small">Status</label><select class="form-select" name="status"><option value="">Todos</option><?php foreach($statuses as $option): ?><option <?= $status===$option?'selected':'' ?>><?= $option ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label small">Subcategoria</label><select class="form-select" name="subcategory"><option value="">Todas</option><?php foreach($subcategoryOptions as $code=>$name): ?><option value="<?= $code ?>" <?= $subcategoryFilter===$code?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-primary"><i data-lucide="filter"></i> Filtrar</button></div></div></form><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Código / peça</th><th>Categoria</th><th>Subcategoria</th><th>Preço</th><th>Origem</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><span class="stock-photo"><i data-lucide="<?= e(category_icon($product['category'])) ?>"></i></span> <strong><?= e($product['code']) ?></strong><div><?= e($product['name']) ?></div></td><td><?= e($product['category']) ?></td><td><?= e($product['subcategory']) ?></td><td>R$ <?= number_format((float)$product['price'],2,',','.') ?></td><td><?= e($product['origin']) ?></td><td><span class="status-badge <?= e(status_class($product['status'])) ?>"><?= e($product['status']) ?></span></td><td class="text-nowrap"><a href="clients.php?action=edit&id=<?= $product['id'] ?>" class="btn btn-sm btn-outline-secondary" title="Editar"><i data-lucide="pencil"></i></a> <a href="clients.php?action=delete&id=<?= $product['id'] ?>" data-confirm="Remover esta peça?" class="btn btn-sm btn-outline-danger" title="Excluir"><i data-lucide="trash-2"></i></a></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="7" class="empty">Nenhuma peça encontrada.</td></tr><?php endif; ?></tbody></table></div></div><?php endif; require __DIR__.'/partials/footer.php'; ?>